namespace sv_b81fb3c0d69543979643f2e26b50edf0.Services;

public class WarehouseInfo
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

/// <summary>
/// Scoped service that holds the currently selected warehouse and notifies
/// subscribers when it changes. Scoped = per circuit on Server, so each
/// user gets independent state.
/// </summary>
public class WarehouseState
{
    private string _currentWarehouseId = "wh-1";

    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } =
    [
        new() { Id = "wh-1", Name = "Warehouse A" },
        new() { Id = "wh-2", Name = "Warehouse B" },
        new() { Id = "wh-3", Name = "Warehouse C" },
    ];

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_b81fb3c0d69543979643f2e26b50edf0.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling. Fires OnAlertCountChanged
/// so all subscribed components update together, even though they aren't in a
/// parent-child relationship.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired when polling detects new alert data. All subscribers update together.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Start polling. Uses reference counting so multiple components can
    /// subscribe; polling only stops when all unsubscribe.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount > 1) return; // already polling

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount > 0) return; // other subscribers still active

        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    /// <summary>
    /// Force an immediate refresh (e.g., after warehouse changes).
    /// </summary>
    public async Task RefreshNowAsync()
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        CurrentLowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start
        await RefreshNowAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                await RefreshNowAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

