@implements IDisposable
@inject WarehouseState WarehouseState

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-white">Warehouse:</label>
    <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _handler;
    }
}

@implements IDisposable
@inject InventoryAlertService AlertService

<span class="badge bg-danger rounded-pill">@AlertService.CurrentLowStockCount</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _handler;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.CurrentWarehouseName</h5>
        <p class="card-text">
            Low-stock items:
            <span class="badge bg-danger fs-5">@AlertService.CurrentLowStockCount</span>
        </p>
        <p class="text-muted">Polling every 10 seconds. Switch warehouses in the top bar to see updates.</p>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        _warehouseHandler = async () =>
        {
            await AlertService.RefreshNowAsync();
            await InvokeAsync(StateHasChanged);
        };

        AlertService.OnAlertCountChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling when dashboard is visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;

        // Stop polling when user leaves the page
        AlertService.StopPolling();
    }
}

